import { NextResponse } from 'next/server'
import { featureGate } from '@/lib/features/server'
import { requireAuth, rateLimitOrRespond } from '@/lib/middleware/api'
import { email, sendSms } from '@/lib/legacy/providers'
import { redact } from '@/lib/ai/provider'

/**
 * Delivers an automation's message to the signed-in user's OWN email (and optionally their own mobile).
 * Called by the browser when an automation fires, because the financial data lives on the device.
 * The text is short, already generated by the app, and passed through redaction; no recipient can be chosen.
 */
export async function POST(request) {
  const limited = rateLimitOrRespond(request, { name: 'automation-notify', limit: 20, windowMs: 60 * 60_000 })
  if (limited) return limited
  const { user, response } = await requireAuth()
  if (response) return response
  { const gate = await featureGate(user._id, 'automation'); if (gate) return gate }
  const b = await request.json().catch(() => ({}))
  const title = redact(String(b.title || '').slice(0, 120))
  const body = redact(String(b.body || '').slice(0, 600))
  if (!title || !body) return NextResponse.json({ error: 'Nothing to send' }, { status: 400 })
  const channels = Array.isArray(b.channels) ? b.channels : []
  const out = {}

  if (channels.includes('email')) {
    if (!user.email) out.email = 'no_email_on_account'
    else {
      try { const r = await email({ to: user.email, subject: `Mintmind: ${title}`, text: `${body}\n\nThis is an automation you set up in Mintmind. It only notifies you.`, html: `<p>${body}</p><p style="color:#64748b;font-size:12px">This is an automation you set up in Mintmind. It only notifies you.</p>` }); out.email = r.sent ? 'sent' : r.reason || 'not_configured' } catch { out.email = 'failed' }
    }
  }
  if (channels.includes('sms')) {
    const mobile = String(b.mobile || '')
    if (!/^\+?[0-9 ()-]{8,16}$/.test(mobile)) out.sms = 'no_mobile_in_profile'
    else { const r = await sendSms({ to: mobile, body: `${title}: ${body}`.slice(0, 300) }); out.sms = r.sent ? 'sent' : r.reason || 'not_configured' }
  }
  return NextResponse.json({ deliveries: out })
}
